today_d=datetime.date(2026,8,27)
def parse_d(v):
    if v is None or v=="": return None
    if isinstance(v, datetime.datetime): return v.date()
    if isinstance(v, datetime.date): return v
    s=str(v).strip().replace("/","-")
    try: return datetime.datetime.strptime(s[:10], "%Y-%m-%d").date()
    except: return None
ev_upd=0
for r in range(2, wsE.max_row+1):
    st=wsE.cell(row=r, column=9).value
    if st in ("日程未確定","中止","延期","中止・延期"): continue
    sd=parse_d(wsE.cell(row=r, column=1).value)
    ed=parse_d(wsE.cell(row=r, column=2).value) or sd
    if sd is None: continue
    if ed < today_d: new="終了"
    elif sd <= today_d <= ed: new="開催中"
    else: new="開催予定"
    if new != st:
        wsE.cell(row=r, column=9).value=new
        wsE.cell(row=r, column=10).value=TODAY
        for c in (wsE.cell(row=r,column=9), wsE.cell(row=r,column=10)):
            c.font=Font(name=FONT, size=c.font.size or 11); c.alignment=Alignment(wrap_text=True, vertical="top")
